CREATE TABLE pokemons (
    id        INT,
    name      VARCHAR(50) PRIMARY KEY,
    ko_name   VARCHAR(50),
    type1     pokemon_types_enum NOT NULL,
    type2     pokemon_types_enum,
    ability1  VARCHAR(50),
    ability2  VARCHAR(50),
    ability3  VARCHAR(50),
    height    REAL,
    weight    REAL,
    h         INT,
    a         INT,
    b         INT,
    c         INT,
    d         INT,
    s         INT,
    can_mega  BOOLEAN NOT NULL DEFAULT FALSE,  -- 이 폼에서 메가진화가 가능한가
    is_mega   BOOLEAN NOT NULL DEFAULT FALSE   -- 이 폼 자체가 메가폼인가
);

